// HasDomain applies the HasEdge predicate on the "domain" edge.
func HasDomain() predicate.ResourceDomainBinding {
	return predicate.ResourceDomainBinding(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DomainTable, DomainColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDomainWith applies the HasEdge predicate on the "domain" edge with a given conditions (other predicates).
func HasDomainWith(preds ...predicate.Domain) predicate.ResourceDomainBinding {
	return predicate.ResourceDomainBinding(func(s *sql.Selector) {
		step := newDomainStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ResourceDomainBinding) predicate.ResourceDomainBinding {
	return predicate.ResourceDomainBinding(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ResourceDomainBinding) predicate.ResourceDomainBinding {
	return predicate.ResourceDomainBinding(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ResourceDomainBinding) predicate.ResourceDomainBinding {
	return predicate.ResourceDomainBinding(sql.NotPredicates(p))
}
